// Vault secret "ConnectionStrings--OrdersDb" maps to ConnectionStrings:OrdersDb
// Reload interval configurable for hot secret rotation

public sealed class ConfigHealthCheck : IHealthCheck
{
    private readonly IConfiguration _config;

    public ConfigHealthCheck(IConfiguration config) => _config = config;

    public Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context, CancellationToken ct = default)
    {
        var cs = _config.GetConnectionString("OrdersDb");
        if (string.IsNullOrEmpty(cs))
            return Task.FromResult(HealthCheckResult.Unhealthy("OrdersDb connection missing"));

        // Report presence, never the value
        return Task.FromResult(HealthCheckResult.Healthy("OrdersDb configured"));
    }
}
